(function(root){
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const safeUrl=u=>{try{const x=new URL(u);return ['http:','https:'].includes(x.protocol)?x.href:null}catch{return null}};
 function renderText(text,entities=[]){
  text=String(text||'');const valid=entities.filter(e=>e&&Number.isInteger(e.offset)&&Number.isInteger(e.length)&&e.offset>=0&&e.length>0&&e.offset+e.length<=text.length).slice(0,200),points=[...new Set([0,text.length,...valid.flatMap(e=>[e.offset,e.offset+e.length])])].sort((a,b)=>a-b);let html='';
  for(let i=0;i<points.length-1;i++){const a=points[i],b=points[i+1];let value=esc(text.slice(a,b));const active=valid.filter(e=>e.offset<=a&&e.offset+e.length>=b);for(const e of active.filter(e=>e.type!=='url'&&e.type!=='textUrl')){const tags={bold:['strong',''],italic:['em',''],underline:['u',''],strike:['s',''],code:['code',''],pre:['code',' class="telegram-code"'],blockquote:['span',' class="telegram-quote"'],spoiler:['span',' class="telegram-spoiler" tabindex="0" aria-label="Spoiler; focus or hover to reveal"']},tag=tags[e.type];if(tag)value='<'+tag[0]+tag[1]+'>'+value+'</'+tag[0]+'>'}const link=active.find(e=>e.type==='url'||e.type==='textUrl');if(link){const url=safeUrl(link.type==='url'?text.slice(link.offset,link.offset+link.length):link.url);if(url)value='<a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+value+'</a>'}html+=value}
  return html;
 }
 function renderFeed(posts){const groups=[],seen=new Map();for(const p of posts){const key=p.groupedId?'album:'+p.groupedId:'post:'+p.id;if(seen.has(key))seen.get(key).push(p);else {const group=[p];seen.set(key,group);groups.push(group)}}return groups.map(group=>{const sorted=[...group].sort((a,b)=>a.id-b.id),first=sorted[0],photos=sorted.filter(p=>p.media?.kind==='photo'&&new RegExp('^/api/telegram-media/'+p.id+'\\?v=[a-zA-Z0-9_-]+$').test(p.media.url));return '<article class="telegram-post"><header><span class="telegram-avatar" aria-hidden="true">↗</span><div><strong>@lmwmnews</strong><small>'+esc(new Date(first.at).toLocaleString())+(group.some(p=>p.edited)?' · Edited':'')+'</small></div><a class="telegram-source-link" target="_blank" rel="noopener noreferrer" href="'+esc(first.url)+'">Open post ↗</a></header>'+(photos.length?'<div class="telegram-photos '+(photos.length>1?'telegram-album':'')+'">'+photos.map(p=>'<a href="'+esc(p.media.url)+'" target="_blank" rel="noopener noreferrer"><img loading="lazy" src="'+esc(p.media.url)+'" alt="Photo from @lmwmnews post '+p.id+'" onerror="this.hidden=true;this.parentElement.nextElementSibling.hidden=false"><span class="telegram-photo-open">View image</span></a><p class="telegram-image-error" hidden>Image unavailable. <a href="'+esc(p.url)+'" target="_blank" rel="noopener noreferrer">View in Telegram ↗</a></p>').join('')+'</div>':'')+sorted.filter(p=>p.title).map(p=>'<div class="telegram-post-text">'+renderText(p.title,p.entities)+'</div>').join('')+'</article>'}).join('')}
 root.TelegramPosts={renderText,renderFeed};
})(typeof window!=='undefined'?window:globalThis);
